views = ["A","B","A","C","A","B","D","A","C","B"]
cache, calls = {}, 0
for w in views:
    if "history" not in cache:
        calls += 1
        cache["history"] = {"A": 3, "B": 1}
    cache["history"][w] = cache["history"].get(w, 0) + 1
print(len(views), "->", calls)
